insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7cdbfd4e-65d7-5160-b69f-87990dd11f00', '889435ea-32e0-4b03-ab10-97e68c0eef82', '80', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ إِسْمَعِيلَ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ مُشْرِكُو ‏ ‏قُرَيْشٍ ‏ ‏يُخَاصِمُونَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْقَدَرِ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏يَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُوا مَسَّ ‏ ‏سَقَرَ ‏ ‏إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ ‏}', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ed2c30c2-2e1b-535c-aef1-7b68e212f575', '889435ea-32e0-4b03-ab10-97e68c0eef82', '81', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عُثْمَانَ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَ لَهَا شَيْئًا مِنْ الْقَدَرِ فَقَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَكَلَّمَ فِي شَيْءٍ مِنْ الْقَدَرِ سُئِلَ عَنْهُ يَوْمَ الْقِيَامَةِ وَمَنْ لَمْ يَتَكَلَّمْ فِيهِ لَمْ يُسْأَلْ عَنْهُ ‏ ‏قَالَ ‏ ‏أَبُو الْحَسَنِ الْقَطَّانُ ‏ ‏حَدَّثَنَاهُ ‏ ‏حَازِمُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ شَيْبَانَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عُثْمَانَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e1787c52-e023-5109-b30e-42aec401eab9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '82', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى أَصْحَابِهِ وَهُمْ يَخْتَصِمُونَ فِي الْقَدَرِ فَكَأَنَّمَا ‏ ‏يُفْقَأُ ‏ ‏فِي وَجْهِهِ حَبُّ الرُّمَّانِ مِنْ الْغَضَبِ فَقَالَ ‏ ‏بِهَذَا أُمِرْتُمْ ‏ ‏أَوْ لِهَذَا خُلِقْتُمْ ‏ ‏تَضْرِبُونَ الْقُرْآنَ بَعْضَهُ بِبَعْضٍ بِهَذَا هَلَكَتْ الْأُمَمُ قَبْلَكُمْ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏مَا غَبَطْتُ نَفْسِي بِمَجْلِسٍ تَخَلَّفْتُ فِيهِ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا غَبَطْتُ نَفْسِي بِذَلِكَ الْمَجْلِسِ وَتَخَلُّفِي عَنْهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9fb6e279-56cb-5ac5-8d21-0d3be27205be', '889435ea-32e0-4b03-ab10-97e68c0eef82', '83', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي حَيَّةَ أَبُو جَنَابٍ الْكَلْبِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا ‏ ‏هَامَةَ ‏ ‏فَقَامَ إِلَيْهِ رَجُلٌ أَعْرَابِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ الْبَعِيرَ يَكُونُ بِهِ الْجَرَبُ فَيُجْرِبُ الْإِبِلَ كُلَّهَا قَالَ ذَلِكُمْ الْقَدَرُ فَمَنْ أَجْرَبَ الْأَوَّلَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b6fa42d-98d1-5d24-abe4-8b6f8c349105', '889435ea-32e0-4b03-ab10-97e68c0eef82', '84', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عِيسَى الْجَرَّارُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى بْنِ أَبِي الْمُسَاوِرِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏عَدِيُّ ابْنُ حَاتِمٍ ‏ ‏الْكُوفَةَ ‏ ‏أَتَيْنَاهُ فِي نَفَرٍ مِنْ فُقَهَاءِ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏فَقُلْنَا لَهُ حَدِّثْنَا مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏عَدِيَّ ابْنَ حَاتِمٍ ‏ ‏أَسْلِمْ تَسْلَمْ قُلْتُ وَمَا الْإِسْلَامُ فَقَالَ ‏ ‏تَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ وَتُؤْمِنُ بِالْأَقْدَارِ كُلِّهَا لِخَيْرِهَا وَشَرِّهَا حُلْوِهَا وَمُرِّهَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3cccc0d5-3ac9-5105-8358-c1eda206b2f2', '889435ea-32e0-4b03-ab10-97e68c0eef82', '85', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّقَاشِيِّ ‏ ‏عَنْ ‏ ‏غُنَيْمِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْقَلْبِ مَثَلُ الرِّيشَةِ تُقَلِّبُهَا الرِّيَاحُ ‏ ‏بِفَلَاةٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1f1f5fbd-34c9-5a34-8a16-2fb81d30875e', '889435ea-32e0-4b03-ab10-97e68c0eef82', '86', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِي ‏ ‏يَعْلَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي ‏ ‏جَارِيَةً ‏ ‏أَعْزِلُ ‏ ‏عَنْهَا قَالَ ‏ ‏سَيَأْتِيهَا مَا قُدِّرَ لَهَا فَأَتَاهُ بَعْدَ ذَلِكَ فَقَالَ قَدْ حَمَلَتْ ‏ ‏الْجَارِيَةُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قُدِّرَ لِنَفْسٍ شَيْءٌ إِلَّا هِيَ ‏ ‏كَائِنَةٌ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e22fddc1-5cc2-51fa-aed8-fbf79ce70e43', '889435ea-32e0-4b03-ab10-97e68c0eef82', '87', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزِيدُ فِي الْعُمْرِ إِلَّا ‏ ‏الْبِرُّ ‏ ‏وَلَا يَرُدُّ الْقَدَرَ إِلَّا الدُّعَاءُ وَإِنَّ الرَّجُلَ لَيُحْرَمُ الرِّزْقَ بِخَطِيئَةٍ يَعْمَلُهَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c790afa6-826b-52d9-a152-126736c63195', '889435ea-32e0-4b03-ab10-97e68c0eef82', '88', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ مُسْلِمٍ الْخَفَّافُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏سُرَاقَةَ بْنِ جُعْشُمٍ ‏ ‏قَالَ قُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ الْعَمَلُ فِيمَا جَفَّ بِهِ الْقَلَمُ وَجَرَتْ بِهِ الْمَقَادِيرُ أَمْ فِي أَمْرٍ مُسْتَقْبَلٍ قَالَ ‏ ‏بَلْ فِيمَا جَفَّ بِهِ الْقَلَمُ وَجَرَتْ بِهِ الْمَقَادِيرُ وَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bb45b256-83b9-5535-83d5-c58f5dab1f83', '889435ea-32e0-4b03-ab10-97e68c0eef82', '89', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُصَفَّى الْحِمْصِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏مَجُوسَ ‏ ‏هَذِهِ الْأُمَّةِ الْمُكَذِّبُونَ بِأَقْدَارِ اللَّهِ إِنْ مَرِضُوا فَلَا ‏ ‏تَعُودُوهُمْ ‏ ‏وَإِنْ مَاتُوا فَلَا تَشْهَدُوهُمْ وَإِنْ لَقِيتُمُوهُمْ فَلَا تُسَلِّمُوا عَلَيْهِمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cf633277-e8d3-5fc0-9753-1355f9027c95', '889435ea-32e0-4b03-ab10-97e68c0eef82', '90', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا إِنِّي أَبْرَأُ إِلَى كُلِّ ‏ ‏خَلِيلٍ ‏ ‏مِنْ ‏ ‏خُلَّتِهِ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَلِيلًا ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ قَالَ ‏ ‏وَكِيعٌ ‏ ‏يَعْنِي نَفْسَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('87c63ce1-3c16-5d60-a2c3-10422be722e4', '889435ea-32e0-4b03-ab10-97e68c0eef82', '91', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَفَعَنِي مَالٌ قَطُّ مَا نَفَعَنِي مَالُ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَبَكَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَقَالَ هَلْ أَنَا وَمَالِي إِلَّا لَكَ يَا رَسُولَ اللَّهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c278d249-a034-5688-b476-abfe2ed1f517', '889435ea-32e0-4b03-ab10-97e68c0eef82', '92', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏سَيِّدَا ‏ ‏كُهُولِ ‏ ‏أَهْلِ الْجَنَّةِ مِنْ الْأَوَّلِينَ وَالْآخِرِينَ إِلَّا النَّبِيِّينَ وَالْمُرْسَلِينَ لَا تُخْبِرْهُمَا يَا ‏ ‏عَلِيُّ ‏ ‏مَا دَامَا حَيَّيْنِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b8cd747-7fbd-5a62-a9bc-1e02b6864392', '889435ea-32e0-4b03-ab10-97e68c0eef82', '93', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏وَعَمْرُو بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى ‏ ‏يَرَاهُمْ مَنْ أَسْفَلَ مِنْهُمْ كَمَا ‏ ‏يُرَى الْكَوْكَبُ الطَّالِعُ فِي الْأُفُقِ مِنْ آفَاقِ السَّمَاءِ وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8d24f75b-036f-5aa7-94f1-451446056743', '889435ea-32e0-4b03-ab10-97e68c0eef82', '94', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏وَحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِرِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ بْنِ الْيَمَانِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَا ‏ ‏أَدْرِي مَا قَدْرُ بَقَائِي فِيكُمْ فَاقْتَدُوا بِاللَّذَيْنِ مِنْ بَعْدِي وَأَشَارَ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a89a02a-e168-5d6a-9d34-7e8714bee855', '889435ea-32e0-4b03-ab10-97e68c0eef82', '95', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعِيدِ بْنِ أَبِي حُسَيْنٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏لَمَّا وُضِعَ ‏ ‏عُمَرُ ‏ ‏عَلَى سَرِيرِهِ اكْتَنَفَهُ النَّاسُ يَدْعُونَ وَيُصَلُّونَ ‏ ‏أَوْ قَالَ يُثْنُونَ وَيُصَلُّونَ ‏ ‏عَلَيْهِ قَبْلَ أَنْ يُرْفَعَ وَأَنَا فِيهِمْ فَلَمْ ‏ ‏يَرُعْنِي ‏ ‏إِلَّا رَجُلٌ قَدْ زَحَمَنِي وَأَخَذَ ‏ ‏بِمَنْكِبِي ‏ ‏فَالْتَفَتُّ فَإِذَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏فَتَرَحَّمَ عَلَى ‏ ‏عُمَرَ ‏ ‏ثُمَّ قَالَ مَا خَلَّفْتُ أَحَدًا أَحَبَّ إِلَيَّ أَنْ أَلْقَى اللَّهَ بِمِثْلِ عَمَلِهِ مِنْكَ وَايْمُ اللَّهِ إِنْ كُنْتُ لَأَظُنُّ لَيَجْعَلَنَّكَ اللَّهُ عَزَّ وَجَلَّ مَعَ صَاحِبَيْكَ وَذَلِكَ أَنِّي كُنْتُ أَكْثَرُ أَنْ أَسْمَعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ذَهَبْتُ أَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَدَخَلْتُ أَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَخَرَجْتُ أَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَكُنْتُ أَظُنُّ لَيَجْعَلَنَّكَ اللَّهُ مَعَ صَاحِبَيْكَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4bc86de5-19fd-5279-8ec4-3cfded3a9c7e', '889435ea-32e0-4b03-ab10-97e68c0eef82', '96', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مَيْمُونٍ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏فَقَالَ ‏ ‏هَكَذَا نُبْعَثُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9b17732e-d2a7-5e2b-94b2-5d7da84b2616', '889435ea-32e0-4b03-ab10-97e68c0eef82', '97', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو شُعَيْبٍ صَالِحُ بْنُ الْهَيْثَمِ الْوَاسِطِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ بَكْرِ بْنِ خُنَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏سَيِّدَا ‏ ‏كُهُولِ ‏ ‏أَهْلِ الْجَنَّةِ مِنْ الْأَوَّلِينَ وَالْآخِرِينَ إِلَّا النَّبِيِّينَ وَالْمُرْسَلِينَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a054b83-8c87-5451-ac3d-05ba4cc299f3', '889435ea-32e0-4b03-ab10-97e68c0eef82', '98', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ ‏ ‏وَالْحُسَيْنُ بْنُ الْحَسَنِ الْمَرْوَزِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ أَيُّ النَّاسِ أَحَبُّ إِلَيْكَ قَالَ ‏ ‏عَائِشَةُ ‏ ‏قِيلَ مِنْ الرِّجَالِ قَالَ أَبُوهَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('903612f7-b06b-5a98-a9c7-86f54be5b568', '889435ea-32e0-4b03-ab10-97e68c0eef82', '99', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏أَخْبَرَنِي ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَيُّ أَصْحَابِهِ كَانَ أَحَبَّ إِلَيْهِ قَالَتْ ‏ ‏أَبُو بَكْرٍ ‏ ‏قُلْتُ ثُمَّ أَيُّهُمْ قَالَتْ ‏ ‏عُمَرُ ‏ ‏قُلْتُ ثُمَّ أَيُّهُمْ قَالَتْ ‏ ‏أَبُو عُبَيْدَةَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5f67f892-539e-5786-96fe-d94ee4dde507', '889435ea-32e0-4b03-ab10-97e68c0eef82', '100', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُحَمَّدٍ الطَّلْحِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ خِرَاشٍ الْحَوْشَبِيُّ ‏ ‏عَنْ ‏ ‏الْعَوَّامِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَسْلَمَ ‏ ‏عُمَرُ ‏ ‏نَزَلَ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏لَقَدْ اسْتَبْشَرَ أَهْلُ السَّمَاءِ بِإِسْلَامِ ‏ ‏عُمَرَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('36cd0b69-3834-56f2-8413-623f7377dc36', '889435ea-32e0-4b03-ab10-97e68c0eef82', '101', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُحَمَّدٍ الطَّلْحِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏دَاوُدُ بْنُ عَطَاءٍ الْمَدِينِيُّ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَّلُ مَنْ يُصَافِحُهُ الْحَقُّ ‏ ‏عُمَرُ ‏ ‏وَأَوَّلُ مَنْ يُسَلِّمُ عَلَيْهِ وَأَوَّلُ مَنْ يَأْخُذُ بِيَدِهِ فَيُدْخِلُهُ الْجَنَّةَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('24558ae8-fc72-5829-a0fe-81b9b1c99e9a', '889435ea-32e0-4b03-ab10-97e68c0eef82', '102', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ أَبُو عُبَيْدٍ الْمَدِينِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ الْمَاجِشُونِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزَّنْجِيُّ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ أَعِزَّ الْإِسْلَامَ ‏ ‏بِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏خَاصَّةً ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('83719afe-06c1-55f3-822d-5c09a69bf51c', '889435ea-32e0-4b03-ab10-97e68c0eef82', '103', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏يَقُولُ ‏ ‏خَيْرُ النَّاسِ بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَخَيْرُ النَّاسِ بَعْدَ ‏ ‏أَبِي بَكْرٍ ‏ ‏عُمَرُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b0f625a6-766a-5e32-8fea-ee29a23046d7', '889435ea-32e0-4b03-ab10-97e68c0eef82', '104', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَارِثِ الْمِصْرِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا نَائِمٌ رَأَيْتُنِي فِي الْجَنَّةِ فَإِذَا أَنَا بِامْرَأَةٍ تَتَوَضَّأُ إِلَى جَانِبِ قَصْرٍ فَقُلْتُ لِمَنْ هَذَا الْقَصْرُ فَقَالَتْ ‏ ‏لِعُمَرَ ‏ ‏فَذَكَرْتُ غَيْرَتَهُ فَوَلَّيْتُ مُدْبِرًا قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَبَكَى ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَقَالَ أَعَلَيْكَ بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ أَغَارُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7ece00ff-6736-5c83-a808-34b8b8b395a6', '889435ea-32e0-4b03-ab10-97e68c0eef82', '105', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ يَحْيَى بْنُ خَلَفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏غُضَيْفِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ وَضَعَ الْحَقَّ عَلَى لِسَانِ ‏ ‏عُمَرَ ‏ ‏يَقُولُ بِهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3a379bb4-fe88-57c6-850a-6282f05f375b', '889435ea-32e0-4b03-ab10-97e68c0eef82', '106', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَرْوَانَ مُحَمَّدُ بْنُ عُثْمَانَ الْعُثْمَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي عُثْمَانُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ نَبِيٍّ رَفِيقٌ فِي الْجَنَّةِ وَرَفِيقِي فِيهَا ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('59859279-4fa1-50aa-8eda-d0f3eb2ca0f4', '889435ea-32e0-4b03-ab10-97e68c0eef82', '107', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَرْوَانَ مُحَمَّدُ بْنُ عُثْمَانَ الْعُثْمَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي عُثْمَانُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِيَ ‏ ‏عُثْمَانَ ‏ ‏عِنْدَ بَابِ الْمَسْجِدِ فَقَالَ يَا ‏ ‏عُثْمَانُ ‏ ‏هَذَا ‏ ‏جِبْرِيلُ ‏ ‏أَخْبَرَنِي أَنَّ ‏ ‏اللَّهَ قَدْ زَوَّجَكَ ‏ ‏أُمَّ كُلْثُومٍ ‏ ‏بِمِثْلِ ‏ ‏صَدَاقِ ‏ ‏رُقَيَّةَ ‏ ‏عَلَى مِثْلِ صُحْبَتِهَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d8de9e03-e853-53e2-9a88-283dbd3a318a', '889435ea-32e0-4b03-ab10-97e68c0eef82', '108', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِتْنَةً فَقَرَّبَهَا فَمَرَّ رَجُلٌ ‏ ‏مُقَنَّعٌ ‏ ‏رَأْسُهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا يَوْمَئِذٍ عَلَى الْهُدَى فَوَثَبْتُ فَأَخَذْتُ بِضَبْعَيْ ‏ ‏عُثْمَانَ ‏ ‏ثُمَّ اسْتَقْبَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ هَذَا قَالَ هَذَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d4226801-bdde-5977-8a43-f2c21427cc1f', '889435ea-32e0-4b03-ab10-97e68c0eef82', '109', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ الدِّمَشْقِيِّ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عُثْمَانُ ‏ ‏إِنْ وَلَّاكَ اللَّهُ هَذَا الْأَمْرَ يَوْمًا فَأَرَادَكَ الْمُنَافِقُونَ أَنْ تَخْلَعَ قَمِيصَكَ الَّذِي قَمَّصَكَ اللَّهُ فَلَا تَخْلَعْهُ يَقُولُ ذَلِكَ ثَلَاثَ مَرَّاتٍ ‏ ‏قَالَ ‏ ‏النُّعْمَانُ ‏ ‏فَقُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا مَنَعَكِ أَنْ تُعْلِمِي النَّاسَ بِهَذَا قَالَتْ أُنْسِيتُهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b21f8c78-2d2e-5ee2-b591-a4904444ef81', '889435ea-32e0-4b03-ab10-97e68c0eef82', '110', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏وَعَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ ‏ ‏وَدِدْتُ أَنَّ عِنْدِي بَعْضَ أَصْحَابِي قُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَدْعُو لَكَ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَسَكَتَ قُلْنَا أَلَا ‏ ‏نَدْعُو لَكَ ‏ ‏عُمَرَ ‏ ‏فَسَكَتَ قُلْنَا أَلَا ‏ ‏نَدْعُو لَكَ ‏ ‏عُثْمَانَ ‏ ‏قَالَ نَعَمْ فَجَاءَ فَخَلَا بِهِ فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَلِّمُهُ وَوَجْهُ ‏ ‏عُثْمَانَ ‏ ‏يَتَغَيَّرُ ‏ ‏قَالَ ‏ ‏قَيْسٌ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبُو سَهْلَةَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏قَالَ يَوْمَ الدَّارِ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهِدَ ‏ ‏إِلَيَّ ‏ ‏عَهْدًا ‏ ‏فَأَنَا صَائِرٌ إِلَيْهِ ‏ ‏وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏فِي حَدِيثِهِ وَأَنَا صَابِرٌ عَلَيْهِ ‏ ‏قَالَ ‏ ‏قَيْسٌ ‏ ‏فَكَانُوا يُرَوْنَهُ ذَلِكَ الْيَوْمَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('41296864-7129-5be5-95b3-cfeeacd95a41', '889435ea-32e0-4b03-ab10-97e68c0eef82', '111', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏وعَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَهِدَ ‏ ‏إِلَيَّ النَّبِيُّ الْأُمِّيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ لَا يُحِبُّنِي إِلَّا مُؤْمِنٌ وَلَا يُبْغِضُنِي إِلَّا مُنَافِقٌ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('757eeb83-680a-5b5c-9c41-b2aabcba3668', '889435ea-32e0-4b03-ab10-97e68c0eef82', '112', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَلِيٍّ ‏ ‏أَلَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('846032d9-cc03-54c7-9c65-da92bc5877c9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '113', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْحُسَيْنِ ‏ ‏أَخْبَرَنِي ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّتِهِ الَّتِي حَجَّ فَنَزَلَ فِي بَعْضِ الطَّرِيقِ فَأَمَرَ الصَّلَاةَ جَامِعَةً فَأَخَذَ بِيَدِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏أَلَسْتُ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ قَالُوا بَلَى قَالَ أَلَسْتُ أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ قَالُوا بَلَى قَالَ فَهَذَا ‏ ‏وَلِيُّ ‏ ‏مَنْ أَنَا ‏ ‏مَوْلَاهُ ‏ ‏اللَّهُمَّ ‏ ‏وَالِ ‏ ‏مَنْ وَالَاهُ اللَّهُمَّ عَادِ مَنْ عَادَاهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9782b6d1-38bb-5e24-8d11-21bd704796d2', '889435ea-32e0-4b03-ab10-97e68c0eef82', '114', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو لَيْلَى ‏ ‏يَسْمُرُ ‏ ‏مَعَ ‏ ‏عَلِيٍّ ‏ ‏فَكَانَ يَلْبَسُ ثِيَابَ الصَّيْفِ فِي الشِّتَاءِ وَثِيَابَ الشِّتَاءِ فِي الصَّيْفِ فَقُلْنَا لَوْ سَأَلْتَهُ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ إِلَيَّ وَأَنَا أَرْمَدُ الْعَيْنِ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَرْمَدُ الْعَيْنِ ‏ ‏فَتَفَلَ فِي عَيْنِي ثُمَّ قَالَ اللَّهُمَّ أَذْهِبْ عَنْهُ الْحَرَّ وَالْبَرْدَ قَالَ فَمَا وَجَدْتُ حَرًّا وَلَا بَرْدًا بَعْدَ يَوْمِئِذٍ وَقَالَ لَأَبْعَثَنَّ رَجُلًا يُحِبُّ اللَّهَ وَرَسُولَهُ وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ لَيْسَ بِفَرَّارٍ فَتَشَرَّفَ لَهُ النَّاسُ فَبَعَثَ إِلَى ‏ ‏عَلِيٍّ ‏ ‏فَأَعْطَاهَا إِيَّاهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c9e3149-c364-51ac-abf3-8152cf21c6f9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '115', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُوسَى الْوَاسِطِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَسَنُ ‏ ‏وَالْحُسَيْنُ ‏ ‏سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ وَأَبُوهُمَا خَيْرٌ مِنْهُمَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6bfa685a-349a-5237-97d3-f5b156aa11cf', '889435ea-32e0-4b03-ab10-97e68c0eef82', '116', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَسُوَيْدُ بْنُ سَعِيدٍ ‏ ‏وَإِسْمَعِيلُ بْنُ مُوسَى ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏حُبْشِيِّ بْنِ جُنَادَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عَلِيٌّ ‏ ‏مِنِّي وَأَنَا مِنْهُ وَلَا يُؤَدِّي عَنِّي إِلَّا عَلِيٌّ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c08bbfd9-a411-5317-83b3-75360d0b4923', '889435ea-32e0-4b03-ab10-97e68c0eef82', '117', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ الرَّازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏أَنْبَأَنَا ‏ ‏الْعَلَاءُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏أَنَا عَبْدُ اللَّهِ وَأَخُو رَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا الصِّدِّيقُ الْأَكْبَرُ لَا يَقُولُهَا بَعْدِي إِلَّا كَذَّابٌ صَلَّيْتُ قَبْلَ النَّاسِ بِسَبْعِ سِنِينَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad15d82a-1a5c-5398-b13a-71d982537738', '889435ea-32e0-4b03-ab10-97e68c0eef82', '118', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ سَابِطٍ وَهُوَ عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏مُعَاوِيَةُ ‏ ‏فِي بَعْضِ حَجَّاتِهِ فَدَخَلَ عَلَيْهِ ‏ ‏سَعْدٌ ‏ ‏فَذَكَرُوا ‏ ‏عَلِيًّا ‏ ‏فَنَالَ مِنْهُ فَغَضِبَ ‏ ‏سَعْدٌ ‏ ‏وَقَالَ تَقُولُ هَذَا لِرَجُلٍ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كُنْتُ ‏ ‏مَوْلَاهُ ‏ ‏فَعَلِيٌّ ‏ ‏مَوْلَاهُ ‏ ‏وَسَمِعْتُهُ يَقُولُ أَنْتَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏إِلَّا أَنَّهُ لَا نَبِيَّ بَعْدِي وَسَمِعْتُهُ يَقُولُ لَأُعْطِيَنَّ الرَّايَةَ الْيَوْمَ رَجُلًا يُحِبُّ اللَّهَ وَرَسُولَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e48df17a-441c-58dc-a651-56a9f2e35bc5', '889435ea-32e0-4b03-ab10-97e68c0eef82', '119', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏قُرَيْظَةَ ‏ ‏مَنْ يَأْتِينَا بِخَبَرِ الْقَوْمِ فَقَالَ ‏ ‏الزُّبَيْرُ ‏ ‏أَنَا فَقَالَ مَنْ يَأْتِينَا بِخَبَرِ الْقَوْمِ فَقَالَ ‏ ‏الزُّبَيْرُ ‏ ‏أَنَا ثَلَاثًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيٌّ ‏ ‏وَإِنَّ ‏ ‏حَوَارِيَّ ‏ ‏الزُّبَيْرُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9f77461f-f30b-5eae-a9bf-cb76913b78a5', '889435ea-32e0-4b03-ab10-97e68c0eef82', '120', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏لَقَدْ ‏ ‏جَمَعَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَوَيْهِ يَوْمَ ‏ ‏أُحُدٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9e8ec9f4-5731-59ec-9a20-1aedecdb280d', '889435ea-32e0-4b03-ab10-97e68c0eef82', '121', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏وَهَدِيَّةُ بْنُ عَبْدِ الْوَهَّابِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشُةُ ‏ ‏يَا ‏ ‏عُرْوَةُ ‏ ‏كَانَ أَبَوَاكَ مِنْ الَّذِينَ اسْتَجَابُوا لِلَّهِ وَالرَّسُولِ مِنْ بَعْدِ مَا أَصَابَهُمْ ‏ ‏الْقَرْحُ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَالزُّبَيْرُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6f82db88-2df1-57de-9d53-23d4e76d21dc', '889435ea-32e0-4b03-ab10-97e68c0eef82', '122', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏وَعَمْرُو بْنُ عَبْدِ اللَّهِ الْأَوْدِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الصَّلْتُ الْأَزْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏طَلْحَةَ ‏ ‏مَرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏شَهِيدٌ يَمْشِي عَلَى وَجْهِ الْأَرْضِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('58845c1c-0bae-53f6-a22b-24f175b95542', '889435ea-32e0-4b03-ab10-97e68c0eef82', '123', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْأَزْهَرِ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُعَاوِيَةَ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ يَحْيَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏قَالَ ‏ ‏نَظَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏طَلْحَةَ ‏ ‏فَقَالَ هَذَا مِمَّنْ ‏ ‏قَضَى نَحْبَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f3aa9273-2b2b-53f5-9172-f81122e16310', '889435ea-32e0-4b03-ab10-97e68c0eef82', '124', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ سِنَانٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْحَقُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ أَشْهَدُ لَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏طَلْحَةُ ‏ ‏مِمَّنْ ‏ ‏قَضَى نَحْبَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6a7e7618-4b82-5c25-be63-f27483332d31', '889435ea-32e0-4b03-ab10-97e68c0eef82', '125', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ يَدَ ‏ ‏طَلْحَةَ ‏ ‏شَلَّاءَ وَقَى بِهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b1a2ce09-6974-5391-b496-43b4c911290c', '889435ea-32e0-4b03-ab10-97e68c0eef82', '126', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ أَبَوَيْهِ لِأَحَدٍ غَيْرَ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏فَإِنَّهُ قَالَ لَهُ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏ارْمِ ‏ ‏سَعْدُ ‏ ‏فِدَاكَ أَبِي وَأُمِّي ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4070d6c9-57f4-5610-9bee-a16a0a72a53e', '889435ea-32e0-4b03-ab10-97e68c0eef82', '127', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحٍ ‏ ‏أَنْبَأَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَعِيلَ ‏ ‏وَإِسْمَعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُ ‏ ‏لَقَدْ جَمَعَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏أَبَوَيْهِ فَقَالَ ‏ ‏ارْمِ ‏ ‏سَعْدُ ‏ ‏فِدَاكَ أَبِي وَأُمِّي ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9cb4176d-d49e-5122-9dbe-99d4a07b9e0a', '889435ea-32e0-4b03-ab10-97e68c0eef82', '128', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏وَخَالِي ‏ ‏يَعْلَى ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَأَوَّلُ ‏ ‏الْعَرَبِ ‏ ‏رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('71b36652-873f-5c26-9207-da4d0ff9d518', '889435ea-32e0-4b03-ab10-97e68c0eef82', '129', '‏ ‏حَدَّثَنَا ‏ ‏مَسْرُوقُ بْنُ الْمَرْزُبَانِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏هَاشِمِ بْنِ هَاشِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يَقُولَ قَالَ ‏ ‏سَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏مَا أَسْلَمَ أَحَدٌ فِي الْيَوْمِ الَّذِي أَسْلَمْتُ فِيهِ وَلَقَدْ مَكَثْتُ سَبْعَةَ أَيَّامٍ وَإِنِّي لَثُلُثُ الْإِسْلَامِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('67f94260-e9e8-557f-8139-31f075f715af', '889435ea-32e0-4b03-ab10-97e68c0eef82', '130', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏صَدَقَةُ بْنُ الْمُثَنَّى أَبُو الْمُثَنَّى النَّخَعِيُّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رِيَاحِ بْنِ الْحَارِثِ ‏ ‏سَمِعَ ‏ ‏سَعِيدَ بْنَ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَاشِرَ عَشَرَةٍ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُمَرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُثْمَانُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَلِيٌّ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَطَلْحَةُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَالزُّبَيْرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَسَعْدٌ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏فِي الْجَنَّةِ فَقِيلَ لَهُ مَنْ التَّاسِعُ قَالَ أَنَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e6c69b40-7e70-579b-aeb6-aaff22d906b2', '889435ea-32e0-4b03-ab10-97e68c0eef82', '131', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ظَالِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي سَمِعْتُهُ يَقُولُ ‏ ‏اثْبُتْ ‏ ‏حِرَاءُ ‏ ‏فَمَا عَلَيْكَ إِلَّا نَبِيٌّ أَوْ صِدِّيقٌ أَوْ شَهِيدٌ وَعَدَّهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏وَعَلِيٌّ ‏ ‏وَطَلْحَةُ ‏ ‏وَالزُّبَيْرُ ‏ ‏وَسَعْدٌ ‏ ‏وَابْنُ عَوْفٍ ‏ ‏وَسَعِيدُ بْنُ زَيْدٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('943dd4fb-edae-5361-a231-57353836c0ba', '889435ea-32e0-4b03-ab10-97e68c0eef82', '132', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏صِلَةَ بْنِ زُفَرَ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِأَهْلِ ‏ ‏نَجْرَانَ ‏ ‏سَأَبْعَثُ مَعَكُمْ رَجُلًا أَمِينًا حَقَّ أَمِينٍ قَالَ فَتَشَرَّفَ لَهُ النَّاسُ فَبَعَثَ ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae18fe74-5aeb-5480-87c8-b4e36e333a60', '889435ea-32e0-4b03-ab10-97e68c0eef82', '133', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏صِلَةَ بْنِ زُفَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِأَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏هَذَا أَمِينُ هَذِهِ الْأُمَّةِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('257bfd4d-01b4-5279-a941-a66bb80dced2', '889435ea-32e0-4b03-ab10-97e68c0eef82', '134', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ مُسْتَخْلِفًا أَحَدًا عَنْ غَيْرِ مَشُورَةٍ لَاسْتَخْلَفْتُ ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bf43b69c-fd8d-55d7-a4d9-463500269eb5', '889435ea-32e0-4b03-ab10-97e68c0eef82', '135', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْخَلَّالُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏بَشَّرَاهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحَبَّ أَنْ يَقْرَأَ الْقُرْآنَ غَضًّا كَمَا أُنْزِلَ فَلْيَقْرَأْهُ عَلَى قِرَاءَةِ ‏ ‏ابْنِ أُمِّ عَبْدٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0ab555b7-914b-5469-b314-2f21b8cdf174', '889435ea-32e0-4b03-ab10-97e68c0eef82', '136', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْنُكَ عَلَيَّ أَنْ تَرْفَعَ الْحِجَابَ وَأَنْ تَسْمَعَ ‏ ‏سِوَادِي ‏ ‏حَتَّى أَنْهَاكَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b9d6ec1b-6b63-52b5-b375-0df38f4de197', '889435ea-32e0-4b03-ab10-97e68c0eef82', '137', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَرِيفٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سَبْرَةَ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏كُنَّا نَلْقَى ‏ ‏النَّفَرَ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَهُمْ يَتَحَدَّثُونَ فَيَقْطَعُونَ حَدِيثَهُمْ فَذَكَرْنَا ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَتَحَدَّثُونَ فَإِذَا رَأَوْا الرَّجُلَ مِنْ أَهْلِ بَيْتِي قَطَعُوا حَدِيثَهُمْ وَاللَّهِ لَا يَدْخُلُ قَلْبَ رَجُلٍ الْإِيمَانُ حَتَّى يُحِبَّهُمْ لِلَّهِ وَلِقَرَابَتِهِمْ مِنِّي ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bb3df95f-4d78-5590-b12e-61cc886f56d9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '138', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ الضَّحَّاكِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ اتَّخَذَنِي ‏ ‏خَلِيلًا ‏ ‏كَمَا اتَّخَذَ ‏ ‏إِبْرَاهِيمَ ‏ ‏خَلِيلًا ‏ ‏فَمَنْزِلِي وَمَنْزِلُ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْجَنَّةِ يَوْمَ الْقِيَامَةِ تُجَاهَيْنِ ‏ ‏وَالْعَبَّاسُ ‏ ‏بَيْنَنَا مُؤْمِنٌ بَيْنَ خَلِيلَيْنِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3fbab12b-ccef-5675-99d9-17e5ae60940b', '889435ea-32e0-4b03-ab10-97e68c0eef82', '139', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْحَسَنِ ‏ ‏اللَّهُمَّ إِنِّي أُحِبُّهُ فَأَحِبَّهُ وَأَحِبَّ مَنْ يُحِبُّهُ قَالَ وَضَمَّهُ إِلَى صَدْرِهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6abb733-4b05-509f-b200-d5e2ec1ca1c1', '889435ea-32e0-4b03-ab10-97e68c0eef82', '140', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي عَوْفٍ أَبِي الْجَحَّافِ ‏ ‏وَكَانَ مَرْضِيًّا ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ ‏ ‏الْحَسَنَ ‏ ‏وَالْحُسَيْنَ ‏ ‏فَقَدْ أَحَبَّنِي وَمَنْ أَبْغَضَهُمَا فَقَدْ أَبْغَضَنِي ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ebd29e0d-1f0b-5d04-bd13-2ad1cd28c792', '889435ea-32e0-4b03-ab10-97e68c0eef82', '141', '‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ حُمَيْدِ بْنِ كَاسِبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي رَاشِدٍ ‏ ‏أَنَّ ‏ ‏يَعْلَى بْنَ مُرَّةَ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّهُمْ خَرَجُوا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى طَعَامٍ دُعُوا لَهُ فَإِذَا ‏ ‏حُسَيْنٌ ‏ ‏يَلْعَبُ فِي ‏ ‏السِّكَّةِ ‏ ‏قَالَ فَتَقَدَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَامَ الْقَوْمِ وَبَسَطَ يَدَيْهِ فَجَعَلَ الْغُلَامُ يَفِرُّ هَا هُنَا وَهَا هُنَا وَيُضَاحِكُهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَخَذَهُ فَجَعَلَ إِحْدَى يَدَيْهِ تَحْتَ ذَقْنِهِ وَالْأُخْرَى فِي فَأْسِ رَأْسِهِ فَقَبَّلَهُ وَقَالَ ‏ ‏حُسَيْنٌ ‏ ‏مِنِّي وَأَنَا مِنْ ‏ ‏حُسَيْنٍ ‏ ‏أَحَبَّ اللَّهُ مَنْ أَحَبَّ ‏ ‏حُسَيْنًا ‏ ‏حُسَيْنٌ ‏ ‏سِبْطٌ ‏ ‏مِنْ ‏ ‏الْأَسْبَاطِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏مِثْلَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5e37d7a6-360f-52d4-bca1-8206a3b060b9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '142', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْخَلَّالُ ‏ ‏وَعَلِيُّ بْنُ الْمُنْذِرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو غَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ نَصْرٍ ‏ ‏عَنْ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏صُبَيْحٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلِيٍّ ‏ ‏وَفَاطِمَةَ ‏ ‏وَالْحَسَنِ ‏ ‏وَالْحُسَيْنِ ‏ ‏أَنَا سِلْمٌ لِمَنْ سَالَمْتُمْ وَحَرْبٌ لِمَنْ حَارَبْتُمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dc8d8acd-1bca-50db-abbd-40931cd2de54', '889435ea-32e0-4b03-ab10-97e68c0eef82', '143', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏هَانِئِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَأْذَنَ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْذَنُوا لَهُ مَرْحَبًا بِالطَّيِّبِ الْمُطَيَّبِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('776ba393-1669-54aa-9ee4-27ba22a140a1', '889435ea-32e0-4b03-ab10-97e68c0eef82', '144', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَثَّامُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏هَانِئِ بْنِ هَانِيءٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَمَّارٌ ‏ ‏عَلَى ‏ ‏عَلِيٍّ ‏ ‏فَقَالَ مَرْحَبًا بِالطَّيِّبِ الْمُطَيَّبِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مُلِئَ ‏ ‏عَمَّارٌ ‏ ‏إِيمَانًا إِلَى مُشَاشِهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0d9f637d-f133-5720-bef8-be62c4743e69', '889435ea-32e0-4b03-ab10-97e68c0eef82', '145', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏وَعَمْرُو بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَا ‏ ‏جَمِيعًا ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ سِيَاهٍ ‏ ‏عَنْ ‏ ‏حَبيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَمَّارٌ ‏ ‏مَا عُرِضَ عَلَيْهِ أَمْرَانِ إِلَّا اخْتَارَ الْأَرْشَدَ مِنْهُمَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11935f4c-2286-527b-935c-70a24a487cea', '889435ea-32e0-4b03-ab10-97e68c0eef82', '146', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُوسَى ‏ ‏وَسُوَيْدُ بْنُ سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي رَبِيعَةَ الْإِيَادِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ أَمَرَنِي بِحُبِّ أَرْبَعَةٍ وَأَخْبَرَنِي أَنَّهُ يُحِبُّهُمْ قِيلَ يَا رَسُولَ اللَّهِ مَنْ هُمْ قَالَ ‏ ‏عَلِيٌّ ‏ ‏مِنْهُمْ يَقُولُ ذَلِكَ ثَلَاثًا ‏ ‏وَأَبُو ذَرٍّ ‏ ‏وَسَلْمَانُ ‏ ‏وَالْمِقْدَادُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6f76a66c-371c-5da2-9236-d047c91ba792', '889435ea-32e0-4b03-ab10-97e68c0eef82', '147', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ سَعِيدٍ الدَّارِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ بْنُ قُدَامَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ أَوَّلَ مَنْ أَظْهَرَ إِسْلَامَهُ سَبْعَةٌ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعَمَّارٌ ‏ ‏وَأُمُّهُ ‏ ‏سُمَيَّةُ ‏ ‏وَصُهَيْبٌ ‏ ‏وَبِلَالٌ ‏ ‏وَالْمِقْدَادُ ‏ ‏فَأَمَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَنَعَهُ اللَّهُ بِعَمِّهِ ‏ ‏أَبِي طَالِبٍ ‏ ‏وَأَمَّا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَمَنَعَهُ اللَّهُ بِقَوْمِهِ وَأَمَّا سَائِرُهُمْ فَأَخَذَهُمْ الْمُشْرِكُونَ وَأَلْبَسُوهُمْ أَدْرَاعَ الْحَدِيدِ وَصَهَرُوهُمْ فِي الشَّمْسِ فَمَا مِنْهُمْ مِنْ أَحَدٍ إِلَّا وَقَدْ وَاتَاهُمْ عَلَى مَا أَرَادُوا إِلَّا ‏ ‏بِلَالًا ‏ ‏فَإِنَّهُ هَانَتْ عَلَيْهِ نَفْسُهُ فِي اللَّهِ وَهَانَ عَلَى قَوْمِهِ فَأَخَذُوهُ فَأَعْطَوْهُ الْوِلْدَانَ فَجَعَلُوا يَطُوفُونَ بِهِ فِي ‏ ‏شِعَابِ ‏ ‏مَكَّةَ ‏ ‏وَهُوَ يَقُولُ أَحَدٌ أَحَدٌ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('73d7450b-d7d1-54b8-a592-a90d98dea7de', '889435ea-32e0-4b03-ab10-97e68c0eef82', '148', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ أُوذِيتُ فِي اللَّهِ وَمَا ‏ ‏يُؤْذَى أَحَدٌ وَلَقَدْ أُخِفْتُ فِي اللَّهِ وَمَا يُخَافُ أَحَدٌ وَلَقَدْ أَتَتْ عَلَيَّ ثَالِثَةٌ وَمَا لِي ‏ ‏وَلِبِلَالٍ ‏ ‏طَعَامٌ يَأْكُلُهُ ‏ ‏ذُو كَبِدٍ ‏ ‏إِلَّا مَا ‏ ‏وَارَى ‏ ‏إِبِطُ ‏ ‏بِلَالٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5fe88e5a-80ea-5d4d-bc55-640165e3d0da', '889435ea-32e0-4b03-ab10-97e68c0eef82', '149', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ حَمْزَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏أَنَّ شَاعِرًا مَدَحَ ‏ ‏بِلَالَ بْنَ عَبْدِ اللَّهِ ‏ ‏فَقَالَ ‏ ‏بِلَالُ بْنُ عَبْدِ اللَّهِ ‏ ‏خَيْرُ ‏ ‏بِلَالٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏كَذَبْتَ لَا بَلْ ‏ ‏بِلَالُ ‏ ‏رَسُولِ اللَّهِ خَيْرُ ‏ ‏بِلَالٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e312b9c8-1d00-5886-a3f1-5c04567cf2b9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '150', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏وَعَمْرُو بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي لَيْلَى الْكِنْدِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏خَبَّابٌ ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏فَقَالَ ‏ ‏ادْنُ فَمَا أَحَدٌ أَحَقَّ بِهَذَا الْمَجْلِسِ مِنْكَ إِلَّا ‏ ‏عَمَّارٌ ‏ ‏فَجَعَلَ ‏ ‏خَبَّابٌ ‏ ‏يُرِيهِ آثَارًا بِظَهْرِهِ مِمَّا عَذَّبَهُ الْمُشْرِكُونَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d72cbd9c-517a-5544-b604-05be17123047', '889435ea-32e0-4b03-ab10-97e68c0eef82', '151', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْحَمُ أُمَّتِي بِأُمَّتِي ‏ ‏أَبُو بَكْرٍ ‏ ‏وَأَشَدُّهُمْ فِي دِينِ اللَّهِ ‏ ‏عُمَرُ ‏ ‏وَأَصْدَقُهُمْ حَيَاءً ‏ ‏عُثْمَانُ ‏ ‏وَأَقْضَاهُمْ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏وَأَقْرَؤُهُمْ لِكِتَابِ اللَّهِ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏وَأَعْلَمُهُمْ بِالْحَلَالِ وَالْحَرَامِ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏وَأَفْرَضُهُمْ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَلَا وَإِنَّ لِكُلِّ أُمَّةٍ أَمِينًا وَأَمِينُ هَذِهِ الْأُمَّةِ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏مِثْلَهُ عِنْدَ ‏ ‏ابْنِ قُدَامَةَ ‏ ‏غَيْرَ أَنَّهُ يَقُولُ فِي حَقِّ ‏ ‏زَيْدٍ ‏ ‏وَأَعْلَمُهُمْ بِالْفَرَائِضِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eacbe2e3-8b58-563f-8665-bcee6e94506e', '889435ea-32e0-4b03-ab10-97e68c0eef82', '152', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي حَرْبِ بْنِ أَبِي الْأَسْوَدِ الدِّيْلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا ‏ ‏أَقَلَّتْ ‏ ‏الْغَبْرَاءُ ‏ ‏وَلَا أَظَلَّتْ ‏ ‏الْخَضْرَاءُ ‏ ‏مِنْ رَجُلٍ أَصْدَقَ لَهْجَةً مِنْ ‏ ‏أَبِي ذَرٍّ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cceb747e-bb29-5706-8bd5-53f7ac82dc40', '889435ea-32e0-4b03-ab10-97e68c0eef82', '153', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏أُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرَقَةٌ ‏ ‏مِنْ حَرِيرٍ فَجَعَلَ الْقَوْمُ يَتَدَاوَلُونَهَا بَيْنَهُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَعْجَبُونَ مِنْ هَذَا فَقَالُوا لَهُ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ لَمَنَادِيلُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فِي الْجَنَّةِ خَيْرٌ مِنْ هَذَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c442a5aa-3ee2-5a06-87b4-8c3b0762dc3e', '889435ea-32e0-4b03-ab10-97e68c0eef82', '154', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اهْتَزَّ عَرْشُ الرَّحْمَنِ عَزَّ وَجَلَّ لِمَوْتِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6d8ec88f-ca64-5c14-9751-79a909037990', '889435ea-32e0-4b03-ab10-97e68c0eef82', '155', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏مَا حَجَبَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ أَسْلَمْتُ وَلَا رَآنِي إِلَّا تَبَسَّمَ فِي وَجْهِي وَلَقَدْ شَكَوْتُ إِلَيْهِ أَنِّي لَا أَثْبُتُ عَلَى الْخَيْلِ ‏ ‏فَضَرَبَ بِيَدِهِ فِي صَدْرِي فَقَالَ اللَّهُمَّ ثَبِّتْهُ وَاجْعَلْهُ هَادِيًا مَهْدِيًّا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('767bb6f4-4ad9-5333-99f0-2ccc91c38959', '889435ea-32e0-4b03-ab10-97e68c0eef82', '156', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏جِبْرِيلُ ‏ ‏أَوْ مَلَكٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا تَعُدُّونَ مَنْ شَهِدَ ‏ ‏بَدْرًا ‏ ‏فِيكُمْ قَالُوا خِيَارَنَا قَالَ كَذَلِكَ هُمْ عِنْدَنَا خِيَارُ الْمَلَائِكَةِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5683e8b1-40fd-5d10-9f73-30dd633ef998', '889435ea-32e0-4b03-ab10-97e68c0eef82', '157', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا أَصْحَابِي فَوَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنَّ أَحَدَكُمْ أَنْفَقَ مِثْلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا مَا أَدْرَكَ ‏ ‏مُدَّ ‏ ‏أَحَدِهِمْ وَلَا نَصِيفَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4c026ecc-aad1-5015-ad5b-4e4b769b172c', '889435ea-32e0-4b03-ab10-97e68c0eef82', '158', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏وَعَمْرُو بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏نُسَيْرِ بْنِ ذُعْلُوقٍ ‏ ‏قَالَ كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَقُولُ ‏ ‏لَا تَسُبُّوا ‏ ‏أَصْحَابَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمُقَامُ أَحَدِهِمْ سَاعَةً خَيْرٌ مِنْ عَمَلِ أَحَدِكُمْ عُمْرَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0c4a56e8-6b5b-52aa-b37c-113054c4522c', '889435ea-32e0-4b03-ab10-97e68c0eef82', '159', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏وَعَمْرُو بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ ‏ ‏الْأَنْصَارَ ‏ ‏أَحَبَّهُ اللَّهُ وَمَنْ أَبْغَضَ ‏ ‏الْأَنْصَارَ ‏ ‏أَبْغَضَهُ اللَّهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لِعَدِيٍّ ‏ ‏أَسَمِعْتَهُ مِنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ إِيَّايَ حَدَّثَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2117254d-a7e3-5f7f-8783-10ba941aa4e2', '889435ea-32e0-4b03-ab10-97e68c0eef82', '160', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي فُدَيْكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمُهَيْمِنِ بْنِ عَبَّاسِ بْنِ سَهْلِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَنْصَارُ ‏ ‏شِعَارٌ ‏ ‏وَالنَّاسُ ‏ ‏دِثَارٌ ‏ ‏وَلَوْ أَنَّ النَّاسَ اسْتَقْبَلُوا وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏وَاسْتَقْبَلَتْ ‏ ‏الْأَنْصَارُ ‏ ‏وَادِيًا لَسَلَكْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e4bbeb60-d2c4-5e19-875a-3d01c832c55a', '889435ea-32e0-4b03-ab10-97e68c0eef82', '161', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنِي ‏ ‏كَثِيرُ بْنُ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحِمَ اللَّهُ ‏ ‏الْأَنْصَارَ ‏ ‏وَأَبْنَاءَ ‏ ‏الْأَنْصَارِ ‏ ‏وَأَبْنَاءَ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5f548de9-35de-5592-b2cb-251c5f4e1483', '889435ea-32e0-4b03-ab10-97e68c0eef82', '162', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَأَبُو بَكْرِ بْنُ خَلَّادٍ الْبَاهِلِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ضَمَّنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ وَقَالَ ‏ ‏اللَّهُمَّ عَلِّمْهُ الْحِكْمَةَ وَتَأْوِيلَ الْكِتَابِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('478eb9c3-de1f-534d-bb78-789e4acfc91a', '889435ea-32e0-4b03-ab10-97e68c0eef82', '163', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏وَذَكَرَ ‏ ‏الْخَوَارِجَ ‏ ‏فَقَالَ ‏ ‏فِيهِمْ رَجُلٌ ‏ ‏مُخْدَجُ ‏ ‏الْيَدِ ‏ ‏أَوْ ‏ ‏مَوْدُونُ ‏ ‏الْيَدِ أَوْ ‏ ‏مَثْدُونُ ‏ ‏الْيَدِ ‏ ‏وَلَوْلَا أَنْ ‏ ‏تَبْطَرُوا ‏ ‏لَحَدَّثْتُكُمْ بِمَا وَعَدَ اللَّهُ الَّذِينَ يَقْتُلُونَهُمْ عَلَى لِسَانِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ أَنْتَ سَمِعْتَهُ مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏ثَلَاثَ مَرَّاتٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('950a7148-c708-5123-9fe9-eae70d80611b', '889435ea-32e0-4b03-ab10-97e68c0eef82', '164', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ زُرَارَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ فِي آخِرِ الزَّمَانِ قَوْمٌ أَحْدَاثُ الْأَسْنَانِ ‏ ‏سُفَهَاءُ ‏ ‏الْأَحْلَامِ يَقُولُونَ مِنْ خَيْرِ قَوْلِ النَّاسِ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الْإِسْلَامِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏فَمَنْ لَقِيَهُمْ فَلْيَقْتُلْهُمْ فَإِنَّ قَتْلَهُمْ أَجْرٌ عِنْدَ اللَّهِ لِمَنْ قَتَلَهُمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8015593c-faca-54d1-ba53-73faea6413b3', '889435ea-32e0-4b03-ab10-97e68c0eef82', '165', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏هَلْ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ فِي ‏ ‏الْحَرُورِيَّةِ ‏ ‏شَيْئًا فَقَالَ ‏ ‏سَمِعْتُهُ يَذْكُرُ قَوْمًا يَتَعَبَّدُونَ يَحْقِرُ أَحَدُكُمْ صَلَاتَهُ مَعَ صَلَاتِهِمْ وَصَوْمَهُ مَعَ صَوْمِهِمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏أَخَذَ سَهْمَهُ فَنَظَرَ فِي ‏ ‏نَصْلِهِ ‏ ‏فَلَمْ يَرَ شَيْئًا فَنَظَرَ فِي ‏ ‏رِصَافِهِ ‏ ‏فَلَمْ يَرَ شَيْئًا فَنَظَرَ فِي قِدْحِهِ فَلَمْ يَرَ شَيْئًا فَنَظَرَ فِي الْقُذَذِ فَتَمَارَى هَلْ ‏ ‏يَرَى شَيْئًا أَمْ لَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('60eaef0f-15a4-5ffc-9949-0d9a297eae11', '889435ea-32e0-4b03-ab10-97e68c0eef82', '166', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَعْدِي مِنْ أُمَّتِي ‏ ‏أَوْ سَيَكُونُ بَعْدِي ‏ ‏مِنْ أُمَّتِي قَوْمٌ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حُلُوقَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏ثُمَّ لَا يَعُودُونَ فِيهِ هُمْ شِرَارُ الْخَلْقِ وَالْخَلِيقَةِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الصَّامِتِ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِرَافِعِ بْنِ عَمْرٍو ‏ ‏أَخِي ‏ ‏الْحَكَمِ بْنِ عَمْرٍو الْغِفَارِيِّ ‏ ‏فَقَالَ ‏ ‏وَأَنَا أَيْضًا قَدْ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
