insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1643a4ea-21b5-5cf7-8961-6cf96b2de77c', '889435ea-32e0-4b03-ab10-97e68c0eef82', '168', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْجِعْرَانَةِ ‏ ‏وَهُوَ يَقْسِمُ ‏ ‏التِّبْرَ ‏ ‏وَالْغَنَائِمَ وَهُوَ فِي حِجْرِ ‏ ‏بِلَالٍ ‏ ‏فَقَالَ ‏ ‏رَجُلٌ ‏ ‏اعْدِلْ يَا ‏ ‏مُحَمَّدُ ‏ ‏فَإِنَّكَ لَمْ تَعْدِلْ فَقَالَ ‏ ‏وَيْلَكَ وَمَنْ يَعْدِلُ بَعْدِي إِذَا لَمْ أَعْدِلْ فَقَالَ ‏ ‏عُمَرُ ‏ ‏دَعْنِي يَا رَسُولَ اللَّهِ حَتَّى أَضْرِبَ عُنُقَ هَذَا الْمُنَافِقِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا فِي أَصْحَابٍ ‏ ‏أَوْ أُصَيْحَابٍ ‏ ‏لَهُ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('703ff6cc-e7a4-598a-93db-8fa09f4fb6b0', '889435ea-32e0-4b03-ab10-97e68c0eef82', '169', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ الْأَزْرَقُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَوَارِجُ ‏ ‏كِلَابُ النَّارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fcb270c0-baff-5e11-b7ef-9e17915882e9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '170', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَنْشَأُ نَشْءٌ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏كُلَّمَا خَرَجَ ‏ ‏قَرْنٌ ‏ ‏قُطِعَ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ كُلَّمَا خَرَجَ ‏ ‏قَرْنٌ ‏ ‏قُطِعَ أَكْثَرَ مِنْ عِشْرِينَ مَرَّةً حَتَّى يَخْرُجَ فِي عِرَاضِهِمْ ‏ ‏الدَّجَّالُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c90f1ac2-03ac-58a7-b771-30725cf509db', '889435ea-32e0-4b03-ab10-97e68c0eef82', '171', '‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ خَلَفٍ أَبُو بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ قَوْمٌ فِي آخِرِ الزَّمَانِ ‏ ‏أَوْ فِي هَذِهِ الْأُمَّةِ ‏ ‏يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏أَوْ حُلُوقَهُمْ ‏ ‏سِيمَاهُمْ ‏ ‏التَّحْلِيقُ ‏ ‏إِذَا رَأَيْتُمُوهُمْ ‏ ‏أَوْ إِذَا لَقِيتُمُوهُمْ ‏ ‏فَاقْتُلُوهُمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4ce096ea-c8bd-5d80-a0be-c30001347ede', '889435ea-32e0-4b03-ab10-97e68c0eef82', '172', '‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ أَبِي سَهْلٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏شَرُّ قَتْلَى قُتِلُوا تَحْتَ ‏ ‏أَدِيمِ السَّمَاءِ ‏ ‏وَخَيْرُ قَتِيلٍ مَنْ قَتَلُوا كِلَابُ أَهْلِ النَّارِ قَدْ كَانَ هَؤُلَاءِ مُسْلِمِينَ فَصَارُوا كُفَّارًا قُلْتُ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏هَذَا شَيْءٌ تَقُولُهُ قَالَ بَلْ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('32e5d7d5-ec05-5f5d-bf03-beee701302be', '889435ea-32e0-4b03-ab10-97e68c0eef82', '173', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِي ‏ ‏يَعْلَى ‏ ‏وَوَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ قَالَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ لَا ‏ ‏تَضَامُّونَ ‏ ‏فِي رُؤْيَتِهِ فَإِنْ اسْتَطَعْتُمْ أَنْ لَا ‏ ‏تُغْلَبُوا ‏ ‏عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا ثُمَّ قَرَأَ ‏ { ‏وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ ‏}', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1c72dd3c-1daf-59cc-970a-0ded87c936ca', '889435ea-32e0-4b03-ab10-97e68c0eef82', '174', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عِيسَى الرَّمْلِيُّ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَضَامُّونَ ‏ ‏فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ قَالُوا لَا قَالَ فَكَذَلِكَ لَا ‏ ‏تَضَامُّونَ ‏ ‏فِي رُؤْيَةِ رَبِّكُمْ يَوْمَ الْقِيَامَةِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d4b7d83a-5e50-51d8-a098-ceeb50afea80', '889435ea-32e0-4b03-ab10-97e68c0eef82', '175', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ الْهَمْدَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏أَنَرَى رَبَّنَا قَالَ ‏ ‏تَضَامُّونَ ‏ ‏فِي رُؤْيَةِ الشَّمْسِ فِي الظَّهِيرَةِ فِي غَيْرِ سَحَابٍ قُلْنَا لَا قَالَ فَتَضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ فِي غَيْرِ سَحَابٍ قَالُوا لَا قَالَ إِنَّكُمْ لَا ‏ ‏تَضَارُّونَ ‏ ‏فِي رُؤْيَتِهِ إِلَّا كَمَا ‏ ‏تَضَارُّونَ ‏ ‏فِي رُؤْيَتِهِمَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('04a538ce-de4d-5ed2-9bfb-83961f396a81', '889435ea-32e0-4b03-ab10-97e68c0eef82', '176', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَنَرَى اللَّهَ يَوْمَ الْقِيَامَةِ وَمَا آيَةُ ذَلِكَ فِي خَلْقِهِ قَالَ يَا ‏ ‏أَبَا رَزِينٍ ‏ ‏أَلَيْسَ كُلُّكُمْ ‏ ‏يَرَى الْقَمَرَ ‏ ‏مُخْلِيًا ‏ ‏بِهِ قَالَ قُلْتُ بَلَى قَالَ فَاللَّهُ أَعْظَمُ وَذَلِكَ آيَةٌ فِي خَلْقِهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c512bd70-6142-536a-955b-97cd83272608', '889435ea-32e0-4b03-ab10-97e68c0eef82', '177', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحِكَ رَبُّنَا مِنْ قُنُوطِ عِبَادِهِ وَقُرْبِ غِيَرِهِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَوَ يَضْحَكُ الرَّبُّ قَالَ نَعَمْ قُلْتُ لَنْ نَعْدَمَ مِنْ رَبٍّ يَضْحَكُ خَيْرًا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da64cb69-c90d-596c-980c-fe1b76243b3d', '889435ea-32e0-4b03-ab10-97e68c0eef82', '178', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَيْنَ كَانَ رَبُّنَا قَبْلَ أَنْ يَخْلُقَ خَلْقَهُ قَالَ كَانَ فِي ‏ ‏عَمَاءٍ ‏ ‏مَا تَحْتَهُ هَوَاءٌ وَمَا فَوْقَهُ هَوَاءٌ وَمَا ثَمَّ خَلْقٌ عَرْشُهُ عَلَى الْمَاءِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('21e6f9b5-e547-5c21-ab11-86798a8ca955', '889435ea-32e0-4b03-ab10-97e68c0eef82', '179', '‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ مَسْعَدَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ الْمَازِنِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَهُوَ يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏إِذْ عَرَضَ لَهُ رَجُلٌ فَقَالَ يَا ‏ ‏ابْنَ عُمَرَ ‏ ‏كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ فِي ‏ ‏النَّجْوَى ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُدْنَى الْمُؤْمِنُ مِنْ رَبِّهِ يَوْمَ الْقِيَامَةِ حَتَّى يَضَعَ عَلَيْهِ ‏ ‏كَنَفَهُ ‏ ‏ثُمَّ يُقَرِّرُهُ بِذُنُوبِهِ فَيَقُولُ هَلْ تَعْرِفُ فَيَقُولُ يَا رَبِّ أَعْرِفُ حَتَّى إِذَا بَلَغَ مِنْهُ مَا شَاءَ اللَّهُ أَنْ يَبْلُغَ قَالَ إِنِّي سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا وَأَنَا أَغْفِرُهَا لَكَ الْيَوْمَ قَالَ ثُمَّ يُعْطَى صَحِيفَةَ حَسَنَاتِهِ ‏ ‏أَوْ كِتَابَهُ ‏ ‏بِيَمِينِهِ قَالَ وَأَمَّا الْكَافِرُ ‏ ‏أَوْ الْمُنَافِقُ ‏ ‏فَيُنَادَى عَلَى رُءُوسِ الْأَشْهَادِ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏فِي الْأَشْهَادِ شَيْءٌ مِنْ انْقِطَاعٍ ‏ { ‏هَؤُلَاءِ الَّذِينَ كَذَبُوا عَلَى رَبِّهِمْ أَلَا لَعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ ‏}', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2e60c5d1-8ecf-5d0b-a354-52d721d9c0c0', '889435ea-32e0-4b03-ab10-97e68c0eef82', '180', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الشَّوَارِبِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ الْعَبَّادَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ الرَّقَاشِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَا أَهْلُ الْجَنَّةِ فِي نَعِيمِهِمْ إِذْ سَطَعَ لَهُمْ نُورٌ فَرَفَعُوا رُءُوسَهُمْ فَإِذَا الرَّبُّ قَدْ أَشْرَفَ عَلَيْهِمْ مِنْ فَوْقِهِمْ فَقَالَ السَّلَامُ عَلَيْكُمْ يَا أَهْلَ الْجَنَّةِ قَالَ وَذَلِكَ قَوْلُ اللَّهِ ‏ { ‏سَلَامٌ قَوْلًا مِنْ رَبٍّ رَحِيمٍ ‏} ‏قَالَ فَيَنْظُرُ إِلَيْهِمْ وَيَنْظُرُونَ إِلَيْهِ فَلَا يَلْتَفِتُونَ إِلَى شَيْءٍ مِنْ النَّعِيمِ مَا دَامُوا يَنْظُرُونَ إِلَيْهِ حَتَّى يَحْتَجِبَ عَنْهُمْ وَيَبْقَى نُورُهُ وَبَرَكَتُهُ عَلَيْهِمْ فِي دِيَارِهِمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadith_books (id, slug, name_ar, name_en, source, author_ar, author_en, hadith_count) values ('aaaaaaaa-0000-0000-0000-000000000007', 'muwatta', 'موطأ الإمام مالك', 'Muwatta Malik', 'Open-Hadith-Data (ODbL/DbCL)', 'الإمام مالك', 'Imam Malik', 1595) on conflict (slug) do update set name_ar=excluded.name_ar, name_en=excluded.name_en, source=excluded.source, author_ar=excluded.author_ar, author_en=excluded.author_en, hadith_count=excluded.hadith_count;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8526fcd6-6735-5c10-87c0-128246d6c807', 'aaaaaaaa-0000-0000-0000-000000000007', '1', '‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثِيّ ‏ ‏عَنْ ‏ ‏مَالِك بْن أَنَس ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا فَدَخَلَ عَلَيْهِ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏فَأَخْبَرَهُ أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا وَهُوَ ‏ ‏بِالْكُوفَةِ ‏ ‏فَدَخَلَ عَلَيْهِ ‏ ‏أَبُو مَسْعُودٍ الْأَنْصَارِيُّ ‏ ‏فَقَالَ ‏ ‏مَا هَذَا يَا ‏ ‏مُغِيرَةُ ‏ ‏أَلَيْسَ قَدْ عَلِمْتَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏نَزَلَ فَصَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ بِهَذَا أُمِرْتُ فَقَالَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏اعْلَمْ مَا تُحَدِّثُ بِهِ يَا ‏ ‏عُرْوَةُ ‏ ‏أَوَ إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏هُوَ الَّذِي أَقَامَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقْتَ الصَّلَاةِ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏كَذَلِكَ كَانَ ‏ ‏بَشِيرُ بْنُ أَبِي مَسْعُودٍ الْأَنْصَارِيُّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏وَلَقَدْ حَدَّثَتْنِي ‏ ‏عَائِشَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ فِي حُجْرَتِهَا قَبْلَ أَنْ تَظْهَرَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2de9fe0a-c9f2-52ea-8d21-2bc0e1a8a3a3', 'aaaaaaaa-0000-0000-0000-000000000007', '2', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏أَنَّهُ قَالَ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ وَقْتِ صَلَاةِ الصُّبْحِ قَالَ فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كَانَ مِنْ الْغَدِ ‏ ‏صَلَّى الصُّبْحَ حِينَ طَلَعَ الْفَجْرُ ثُمَّ صَلَّى الصُّبْحَ مِنْ الْغَدِ بَعْدَ أَنْ ‏ ‏أَسْفَرَ ‏ ‏ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ وَقْتِ الصَّلَاةِ قَالَ ‏ ‏هَأَنَذَا يَا رَسُولَ اللَّهِ فَقَالَ مَا بَيْنَ هَذَيْنِ وَقْتٌ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('82e6f3ca-a166-549a-a042-dd9404d3f9a2', 'aaaaaaaa-0000-0000-0000-000000000007', '3', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُصَلِّي الصُّبْحَ فَيَنْصَرِفُ النِّسَاءُ ‏ ‏مُتَلَفِّعَاتٍ ‏ ‏بِمُرُوطِهِنَّ ‏ ‏مَا يُعْرَفْنَ مِنْ ‏ ‏الْغَلَسِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7bb87c5e-e4ee-5582-aa3d-63554a555f6e', 'aaaaaaaa-0000-0000-0000-000000000007', '4', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏وَعَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏وَعَنْ ‏ ‏الْأَعْرَجِ ‏ ‏كُلُّهُمْ يُحَدِّثُونَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ رَكْعَةً مِنْ الصُّبْحِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ الصُّبْحَ وَمَنْ أَدْرَكَ رَكْعَةً مِنْ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ الْعَصْرَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cfdc63a7-8af3-53f1-96e5-d2c2f753af05', 'aaaaaaaa-0000-0000-0000-000000000007', '5', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏كَتَبَ ‏ ‏إِلَى عُمَّالِهِ ‏ ‏إِنَّ أَهَمَّ أَمْرِكُمْ عِنْدِي الصَّلَاةُ فَمَنْ حَفِظَهَا وَحَافَظَ عَلَيْهَا حَفِظَ دِينَهُ وَمَنْ ضَيَّعَهَا فَهُوَ لِمَا سِوَاهَا ‏ ‏أَضْيَعُ ثُمَّ كَتَبَ أَنْ صَلُّوا الظُّهْرَ إِذَا كَانَ ‏ ‏الْفَيْءُ ‏ ‏ذِرَاعًا إِلَى أَنْ يَكُونَ ظِلُّ أَحَدِكُمْ مِثْلَهُ وَالْعَصْرَ وَالشَّمْسُ مُرْتَفِعَةٌ بَيْضَاءُ نَقِيَّةٌ قَدْرَ مَا يَسِيرُ الرَّاكِبُ ‏ ‏فَرْسَخَيْنِ ‏ ‏أَوْ ثَلَاثَةً قَبْلَ غُرُوبِ الشَّمْسِ وَالْمَغْرِبَ إِذَا غَرَبَتْ الشَّمْسُ وَالْعِشَاءَ إِذَا غَابَ ‏ ‏الشَّفَقُ ‏ ‏إِلَى ثُلُثِ اللَّيْلِ فَمَنْ نَامَ فَلَا نَامَتْ عَيْنُهُ فَمَنْ نَامَ فَلَا نَامَتْ عَيْنُهُ فَمَنْ نَامَ فَلَا نَامَتْ عَيْنُهُ وَالصُّبْحَ وَالنُّجُومُ بَادِيَةٌ مُشْتَبِكَةٌ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('66463961-259c-5f44-9fe2-1dd780923e53', 'aaaaaaaa-0000-0000-0000-000000000007', '6', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏كَتَبَ إِلَى ‏ ‏أَبِي مُوسَى ‏ ‏أَنْ ‏ ‏صَلِّ الظُّهْرَ إِذَا زَاغَتْ الشَّمْسُ وَالْعَصْرَ وَالشَّمْسُ بَيْضَاءُ نَقِيَّةٌ قَبْلَ أَنْ يَدْخُلَهَا صُفْرَةٌ وَالْمَغْرِبَ إِذَا غَرَبَتْ الشَّمْسُ وَأَخِّرْ الْعِشَاءَ مَا لَمْ تَنَمْ وَصَلِّ الصُّبْحَ وَالنُّجُومُ بَادِيَةٌ مُشْتَبِكَةٌ وَاقْرَأْ فِيهَا بِسُورَتَيْنِ طَوِيلَتَيْنِ مِنْ ‏ ‏الْمُفَصَّلِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a0c9f8be-0ba9-5003-8a80-f5362621e3c3', 'aaaaaaaa-0000-0000-0000-000000000007', '7', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏كَتَبَ ‏ ‏إِلَى ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏أَنْ ‏ ‏صَلِّ الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ نَقِيَّةٌ قَدْرَ مَا يَسِيرُ الرَّاكِبُ ثَلَاثَةَ ‏ ‏فَرَاسِخَ ‏ ‏وَأَنْ صَلِّ الْعِشَاءَ مَا بَيْنَكَ وَبَيْنَ ثُلُثِ اللَّيْلِ فَإِنْ أَخَّرْتَ فَإِلَى شَطْرِ اللَّيْلِ وَلَا تَكُنْ مِنْ الْغَافِلِينَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('18aebd9c-9208-5e15-8c26-18ca7377e708', 'aaaaaaaa-0000-0000-0000-000000000007', '8', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ وَقْتِ الصَّلَاةِ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَا أُخْبِرُكَ ‏ ‏صَلِّ الظُّهْرَ إِذَا كَانَ ظِلُّكَ مِثْلَكَ وَالْعَصْرَ إِذَا كَانَ ظِلُّكَ مِثْلَيْكَ وَالْمَغْرِبَ إِذَا غَرَبَتْ الشَّمْسُ وَالْعِشَاءَ مَا بَيْنَكَ وَبَيْنَ ثُلُثِ اللَّيْلِ وَصَلِّ الصُّبْحَ بِغَبَشٍ ‏ ‏يَعْنِي ‏ ‏الْغَلَسَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('311ba34e-dc26-5b96-91fb-33ea8ed2f73f', 'aaaaaaaa-0000-0000-0000-000000000007', '9', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي الْعَصْرَ ثُمَّ يَخْرُجُ الْإِنْسَانُ إِلَى ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏فَيَجِدُهُمْ يُصَلُّونَ الْعَصْرَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fd5a9329-2f58-5cf0-8059-cd16ec5d8c31', 'aaaaaaaa-0000-0000-0000-000000000007', '10', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي الْعَصْرَ ثُمَّ يَذْهَبُ الذَّاهِبُ إِلَى ‏ ‏قُبَاءٍ ‏ ‏فَيَأْتِيهِمْ وَالشَّمْسُ مُرْتَفِعَةٌ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('54285d9a-01f8-504d-96b0-4272d0a1009b', 'aaaaaaaa-0000-0000-0000-000000000007', '11', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا أَدْرَكْتُ النَّاسَ إِلَّا وَهُمْ يُصَلُّونَ الظُّهْرَ بِعَشِيٍّ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0d4a526c-16af-5e4f-ae26-7c37703785ba', 'aaaaaaaa-0000-0000-0000-000000000007', '12', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي سُهَيْلِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنْتُ أَرَى ‏ ‏طِنْفِسَةً ‏ ‏لِعَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏يَوْمَ الْجُمُعَةِ تُطْرَحُ إِلَى جِدَارِ الْمَسْجِدِ الْغَرْبِيِّ فَإِذَا غَشِيَ الطِّنْفِسَةَ كُلَّهَا ظِلُّ الْجِدَارِ خَرَجَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَصَلَّى الْجُمُعَةَ ‏ ‏قَالَ ‏ ‏مَالِكٌ ‏ ‏ثُمَّ نَرْجِعُ بَعْدَ صَلَاةِ الْجُمُعَةِ ‏ ‏فَنَقِيلُ ‏ ‏قَائِلَةَ ‏ ‏الضَّحَاءِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e99862c8-0591-5b66-b232-b05680648501', 'aaaaaaaa-0000-0000-0000-000000000007', '13', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي سَلِيطٍ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏صَلَّى الْجُمُعَةَ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَصَلَّى الْعَصْرَ ‏ ‏بِمَلَلٍ ‏ ‏قَالَ ‏ ‏مَالِك ‏ ‏وَذَلِكَ ‏ ‏لِلتَّهْجِيرِ ‏ ‏وَسُرْعَةِ السَّيْرِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
