insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11020ab7-d2b6-574d-a573-ccabbb4c53b1', 'aaaaaaaa-0000-0000-0000-000000000007', '27', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يَقْرُبْ مَسَاجِدَنَا يُؤْذِينَا بِرِيحِ الثُّومِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('962fcb47-c898-534b-aa3f-e8e64f74d898', 'aaaaaaaa-0000-0000-0000-000000000007', '28', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْمُجَبَّرِ ‏ ‏أَنَّهُ كَانَ يَرَى ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏إِذَا رَأَى الْإِنْسَانَ ‏ ‏يُغَطِّي فَاهُ وَهُوَ ‏ ‏يُصَلِّي جَبَذَ الثَّوْبَ عَنْ ‏ ‏فِيهِ جَبْذًا شَدِيدًا حَتَّى يَنْزِعَهُ عَنْ ‏ ‏فِيهِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a5647472-8c4d-5fbc-83f3-5d35aabc8344', 'aaaaaaaa-0000-0000-0000-000000000007', '29', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏وَهُوَ جَدُّ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَسْتَطِيعُ أَنْ تُرِيَنِي كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدِ بْنِ عَاصِمٍ ‏ ‏نَعَمْ ‏ ‏فَدَعَا بِوَضُوءٍ فَأَفْرَغَ عَلَى يَدِهِ فَغَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ ثُمَّ تَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ إِلَى الْمِرْفَقَيْنِ ثُمَّ مَسَحَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ بَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ثُمَّ غَسَلَ رِجْلَيْهِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
