insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cd63997a-5d1a-521f-bce8-ee078752454b', 'aaaaaaaa-0000-0000-0000-000000000007', '51', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ الْأَنْصَارِيِّ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَدِمَ مِنْ ‏ ‏الْعِرَاقِ ‏ ‏فَدَخَلَ عَلَيْهِ ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَأُبَيُّ بْنُ كَعْبٍ ‏ ‏فَقَرَّبَ لَهُمَا طَعَامًا قَدْ مَسَّتْهُ النَّارُ فَأَكَلُوا مِنْهُ فَقَامَ ‏ ‏أَنَسٌ ‏ ‏فَتَوَضَّأَ ‏ ‏فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَأُبَيُّ بْنُ كَعْبٍ ‏ ‏مَا هَذَا يَا ‏ ‏أَنَسُ ‏ ‏أَعِرَاقِيَّةٌ ‏ ‏فَقَالَ ‏ ‏أَنَسٌ ‏ ‏لَيْتَنِي لَمْ أَفْعَلْ وَقَامَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَأُبَيُّ بْنُ كَعْبٍ ‏ ‏فَصَلَّيَا وَلَمْ يَتَوَضَّآَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af3cb102-21f0-5d4c-943f-25366fac6f8e', 'aaaaaaaa-0000-0000-0000-000000000007', '52', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ ‏ ‏الْاسْتِطَابَةِ ‏ ‏فَقَالَ ‏ ‏أَوَلَا يَجِدُ أَحَدُكُمْ ثَلَاثَةَ أَحْجَارٍ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('983761e5-ea16-5b63-a6a7-4dc651557522', 'aaaaaaaa-0000-0000-0000-000000000007', '53', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الْمَقْبُرَةِ فَقَالَ ‏ ‏السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ وَدِدْتُ أَنِّي قَدْ رَأَيْتُ إِخْوَانَنَا فَقَالُوا يَا رَسُولَ اللَّهِ أَلَسْنَا بِإِخْوَانِكَ قَالَ بَلْ أَنْتُمْ أَصْحَابِي وَإِخْوَانُنَا الَّذِينَ لَمْ يَأْتُوا بَعْدُ وَأَنَا ‏ ‏فَرَطُهُمْ ‏ ‏عَلَى الْحَوْضِ فَقَالُوا يَا رَسُولَ اللَّهِ كَيْفَ تَعْرِفُ مَنْ يَأْتِي بَعْدَكَ مِنْ أُمَّتِكَ قَالَ أَرَأَيْتَ لَوْ كَانَ لِرَجُلٍ خَيْلٌ ‏ ‏غُرٌّ ‏ ‏مُحَجَّلَةٌ ‏ ‏فِي خَيْلٍ ‏ ‏دُهْمٍ ‏ ‏بُهْمٍ ‏ ‏أَلَا يَعْرِفُ خَيْلَهُ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَإِنَّهُمْ يَأْتُونَ يَوْمَ الْقِيَامَةِ غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ الْوُضُوءِ وَأَنَا فَرَطُهُمْ عَلَى الْحَوْضِ فَلَا ‏ ‏يُذَادَنَّ ‏ ‏رِجَالٌ عَنْ حَوْضِي كَمَا يُذَادُ الْبَعِيرُ الضَّالُّ ‏ ‏أُنَادِيهِمْ أَلَا هَلُمَّ أَلَا هَلُمَّ أَلَا هَلُمَّ فَيُقَالُ إِنَّهُمْ قَدْ بَدَّلُوا بَعْدَكَ فَأَقُولُ فَسُحْقًا فَسُحْقًا فَسُحْقًا ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('64185c23-be5c-5844-8dfc-da938ce19b00', 'aaaaaaaa-0000-0000-0000-000000000007', '54', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏جَلَسَ عَلَى الْمَقَاعِدِ فَجَاءَ الْمُؤَذِّنُ فَآذَنَهُ بِصَلَاةِ الْعَصْرِ فَدَعَا بِمَاءٍ فَتَوَضَّأَ ثُمَّ قَالَ وَاللَّهِ لَأُحَدِّثَنَّكُمْ حَدِيثًا لَوْلَا أَنَّهُ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمُوهُ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ امْرِئٍ يَتَوَضَّأُ فَيُحْسِنُ وُضُوءَهُ ثُمَّ ‏ ‏يُصَلِّي الصَّلَاةَ إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلَاةِ الْأُخْرَى حَتَّى يُصَلِّيَهَا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏قَالَ ‏ ‏مَالِك ‏ ‏أُرَاهُ يُرِيدُ هَذِهِ الْآيَةَ ‏ { ‏أَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ وَزُلَفًا مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ذَلِكَ ذِكْرَى لِلذَّاكِرِينَ ‏}', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9ed285f4-0f09-5812-96f2-8353432215f0', 'aaaaaaaa-0000-0000-0000-000000000007', '55', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ الْمُؤْمِنُ فَتَمَضْمَضَ خَرَجَتْ الْخَطَايَا مِنْ ‏ ‏فِيهِ وَإِذَا ‏ ‏اسْتَنْثَرَ ‏ ‏خَرَجَتْ الْخَطَايَا مِنْ أَنْفِهِ فَإِذَا غَسَلَ وَجْهَهُ خَرَجَتْ الْخَطَايَا مِنْ وَجْهِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ ‏ ‏أَشْفَارِ ‏ ‏عَيْنَيْهِ فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ الْخَطَايَا مِنْ يَدَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ يَدَيْهِ فَإِذَا مَسَحَ بِرَأْسِهِ خَرَجَتْ الْخَطَايَا مِنْ رَأْسِهِ حَتَّى تَخْرُجَ مِنْ أُذُنَيْهِ فَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتْ الْخَطَايَا مِنْ رِجْلَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ رِجْلَيْهِ قَالَ ثُمَّ كَانَ مَشْيُهُ إِلَى الْمَسْجِدِ وَصَلَاتُهُ نَافِلَةً لَهُ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('209a1851-9e22-5982-b5f8-5d6079bfa759', 'aaaaaaaa-0000-0000-0000-000000000007', '56', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ الْمُسْلِمُ ‏ ‏أَوْ الْمُؤْمِنُ ‏ ‏فَغَسَلَ وَجْهَهُ خَرَجَتْ مِنْ وَجْهِهِ كُلُّ خَطِيئَةٍ نَظَرَ إِلَيْهَا بِعَيْنَيْهِ مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ ‏ ‏فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ مِنْ يَدَيْهِ كُلُّ خَطِيئَةٍ بَطَشَتْهَا يَدَاهُ مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ ‏ ‏فَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتْ كُلُّ خَطِيئَةٍ مَشَتْهَا رِجْلَاهُ مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ ‏ ‏حَتَّى يَخْرُجَ نَقِيًّا مِنْ الذُّنُوبِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d504f2af-e8e7-53d3-adc1-0a95c682e240', 'aaaaaaaa-0000-0000-0000-000000000007', '57', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَانَتْ صَلَاةُ الْعَصْرِ فَالْتَمَسَ النَّاسُ ‏ ‏وَضُوءًا ‏ ‏فَلَمْ يَجِدُوهُ فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَضُوءٍ فِي إِنَاءٍ فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ذَلِكَ الْإِنَاءِ يَدَهُ ثُمَّ أَمَرَ النَّاسَ يَتَوَضَّئُونَ مِنْهُ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَرَأَيْتُ الْمَاءَ يَنْبُعُ مِنْ تَحْتِ أَصَابِعِهِ فَتَوَضَّأَ النَّاسُ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3d17348d-6ef5-52df-97d4-05f64b45c5f5', 'aaaaaaaa-0000-0000-0000-000000000007', '58', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمَدَنِيِّ الْمُجْمِرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ وُضُوءَهُ ثُمَّ خَرَجَ عَامِدًا إِلَى الصَّلَاةِ فَإِنَّهُ فِي صَلَاةٍ مَا دَامَ يَعْمِدُ إِلَى الصَّلَاةِ وَإِنَّهُ يُكْتَبُ لَهُ بِإِحْدَى خُطْوَتَيْهِ حَسَنَةٌ ‏ ‏وَيُمْحَى عَنْهُ بِالْأُخْرَى سَيِّئَةٌ فَإِذَا سَمِعَ أَحَدُكُمْ الْإِقَامَةَ ‏ ‏فَلَا يَسْعَ ‏ ‏فَإِنَّ أَعْظَمَكُمْ أَجْرًا أَبْعَدُكُمْ دَارًا قَالُوا لِمَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ مِنْ أَجْلِ كَثْرَةِ ‏ ‏الْخُطَا ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0557df95-e679-5453-a150-cbe3c689e110', 'aaaaaaaa-0000-0000-0000-000000000007', '59', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يُسْأَلُ عَنْ الْوُضُوءِ مِنْ الْغَائِطِ بِالْمَاءِ فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏إِنَّمَا ذَلِكَ وُضُوءُ النِّسَاءِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bff1881d-e71e-593f-87cb-77fe2145dec1', 'aaaaaaaa-0000-0000-0000-000000000007', '60', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
