insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d9cf6170-b9ab-5d0a-b6f8-5583fe9781dd', 'aaaaaaaa-0000-0000-0000-000000000007', '64', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ زِيَادٍ ‏ ‏مِنْ وَلَدِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ أَبِيهِ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَهَبَ لِحَاجَتِهِ فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏فَذَهَبْتُ مَعَهُ بِمَاءٍ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَكَبْتُ عَلَيْهِ الْمَاءَ فَغَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ يُخْرِجُ يَدَيْهِ مِنْ كُمَّيْ جُبَّتِهِ فَلَمْ يَسْتَطِعْ مِنْ ضِيقِ كُمَّيْ الْجُبَّةِ فَأَخْرَجَهُمَا مِنْ تَحْتِ الْجُبَّةِ فَغَسَلَ يَدَيْهِ وَمَسَحَ بِرَأْسِهِ ‏ ‏وَمَسَحَ عَلَى الْخُفَّيْنِ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏يَؤُمُّهُمْ وَقَدْ صَلَّى بِهِمْ رَكْعَةً فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّكْعَةَ الَّتِي بَقِيَتْ عَلَيْهِمْ فَفَزِعَ النَّاسُ فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَحْسَنْتُمْ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d96ff87b-dc40-5748-827c-e3e4dd85008b', 'aaaaaaaa-0000-0000-0000-000000000007', '65', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏أَنَّهُمَا أَخْبَرَاهُ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَدِمَ ‏ ‏الْكُوفَةَ ‏ ‏عَلَى ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏وَهُوَ أَمِيرُهَا فَرَآهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ فَأَنْكَرَ ذَلِكَ عَلَيْهِ فَقَالَ لَهُ ‏ ‏سَعْدٌ ‏ ‏سَلْ أَبَاكَ إِذَا قَدِمْتَ عَلَيْهِ فَقَدِمَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَنَسِيَ أَنْ يَسْأَلَ ‏ ‏عُمَرَ ‏ ‏عَنْ ذَلِكَ حَتَّى قَدِمَ ‏ ‏سَعْدٌ ‏ ‏فَقَالَ أَسَأَلْتَ أَبَاكَ فَقَالَ لَا فَسَأَلَهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏إِذَا أَدْخَلْتَ رِجْلَيْكَ فِي الْخُفَّيْنِ وَهُمَا طَاهِرَتَانِ فَامْسَحْ عَلَيْهِمَا قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَإِنْ جَاءَ أَحَدُنَا مِنْ الْغَائِطِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏نَعَمْ وَإِنْ جَاءَ أَحَدُكُمْ مِنْ الْغَائِطِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
