insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('783eba03-fff1-5cfe-b79c-628b7701e57d', 'aaaaaaaa-0000-0000-0000-000000000007', '74', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏الْمِسْوَرَ بْنَ مَخْرَمَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏مِنْ اللَّيْلَةِ الَّتِي طُعِنَ فِيهَا فَأَيْقَظَ ‏ ‏عُمَرَ ‏ ‏لِصَلَاةِ الصُّبْحِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏نَعَمْ وَلَا حَظَّ فِي الْإِسْلَامِ لِمَنْ تَرَكَ الصَّلَاةَ فَصَلَّى ‏ ‏عُمَرُ ‏ ‏وَجُرْحُهُ ‏ ‏يَثْعَبُ ‏ ‏دَمًا ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('53512cd4-f05d-5435-83bf-eabc0cc3a172', 'aaaaaaaa-0000-0000-0000-000000000007', '75', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏مَا تَرَوْنَ فِيمَنْ غَلَبَهُ الدَّمُ مِنْ ‏ ‏رُعَافٍ ‏ ‏فَلَمْ يَنْقَطِعْ عَنْهُ ‏ ‏قَالَ ‏ ‏مَالِك ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏ثُمَّ قَالَ ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَرَى أَنْ يُومِئَ بِرَأْسِهِ إِيمَاءً ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏قَالَ ‏ ‏مَالِك ‏ ‏وَذَلِكَ أَحَبُّ مَا سَمِعْتُ إِلَيَّ فِي ذَلِكَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('31b4c733-5a32-5b75-8e46-edaee4700a65', 'aaaaaaaa-0000-0000-0000-000000000007', '76', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏الْمِقْدَادِ بْنِ الْأَسْوَدِ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏أَمَرَهُ أَنْ يَسْأَلَ لَهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ إِذَا دَنَا مِنْ أَهْلِهِ فَخَرَجَ مِنْهُ ‏ ‏الْمَذْيُ ‏ ‏مَاذَا عَلَيْهِ قَالَ ‏ ‏عَلِيٌّ ‏ ‏فَإِنَّ عِنْدِي ابْنَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَسْتَحِي أَنْ أَسْأَلَهُ ‏ ‏قَالَ ‏ ‏الْمِقْدَادُ ‏ ‏فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ ‏ ‏إِذَا وَجَدَ ذَلِكَ أَحَدُكُمْ فَلْيَنْضَحْ فَرْجَهُ بِالْمَاءِ ‏ ‏وَلْيَتَوَضَّأْ وُضُوءَهُ لِلصَّلَاةِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
