insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('720fd2b1-bfd1-5312-80f8-c70c303e76e4', 'aaaaaaaa-0000-0000-0000-000000000007', '80', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏الصَّلْتِ بْنِ زُيَيْدٍ ‏ ‏أَنَّهُ قَالَ سَأَلْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏عَنْ الْبَلَلِ أَجِدُهُ فَقَالَ ‏ ‏انْضَحْ مَا تَحْتَ ثَوْبِكَ بِالْمَاءِ وَالْهُ عَنْهُ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f60aefcf-dcc8-56db-9fdc-2aa27c5f6e42', 'aaaaaaaa-0000-0000-0000-000000000007', '81', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يَقُولُ ‏ ‏دَخَلْتُ عَلَى ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏فَتَذَاكَرْنَا مَا يَكُونُ مِنْهُ الْوُضُوءُ ‏ ‏فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏وَمِنْ مَسِّ الذَّكَرِ الْوُضُوءُ ‏ ‏فَقَالَ ‏ ‏عُرْوَةُ ‏ ‏مَا عَلِمْتُ هَذَا ‏ ‏فَقَالَ ‏ ‏مَرْوَانُ بْنُ الْحَكَمِ ‏ ‏أَخْبَرَتْنِي ‏ ‏بُسْرَةُ بِنْتُ صَفْوَانَ ‏ ‏أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا مَسَّ أَحَدُكُمْ ذَكَرَهُ فَلْيَتَوَضَّأْ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('87a47fd6-587a-5e81-938c-135d3f8ee080', 'aaaaaaaa-0000-0000-0000-000000000007', '82', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ مُحَمَّدِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنْتُ أُمْسِكُ الْمُصْحَفَ عَلَى ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏فَاحْتَكَكْتُ ‏ ‏فَقَالَ ‏ ‏سَعْدٌ ‏ ‏لَعَلَّكَ مَسِسْتَ ذَكَرَكَ قَالَ فَقُلْتُ نَعَمْ فَقَالَ ‏ ‏قُمْ فَتَوَضَّأْ فَقُمْتُ فَتَوَضَّأْتُ ثُمَّ رَجَعْتُ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
