insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('71134ab4-045d-55fa-ba53-056fe659df59', 'aaaaaaaa-0000-0000-0000-000000000007', '85', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ رَأَيْتُ ‏ ‏أَبِي ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَغْتَسِلُ ثُمَّ يَتَوَضَّأُ فَقُلْتُ لَهُ يَا ‏ ‏أَبَتِ أَمَا ‏ ‏يَجْزِيكَ الْغُسْلُ مِنْ الْوُضُوءِ قَالَ بَلَى وَلَكِنِّي ‏ ‏أَحْيَانًا أَمَسُّ ذَكَرِي فَأَتَوَضَّأُ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
