insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3cedaedd-47ba-5616-afdb-63587e274ebf', 'aaaaaaaa-0000-0000-0000-000000000007', '100', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ أَبِي حَكِيمٍ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَسَارٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَبَّرَ فِي صَلَاةٍ مِنْ الصَّلَوَاتِ ثُمَّ أَشَارَ إِلَيْهِمْ بِيَدِهِ أَنْ امْكُثُوا فَذَهَبَ ثُمَّ رَجَعَ وَعَلَى جِلْدِهِ أَثَرُ الْمَاءِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('050b7e82-d2da-5904-9dc4-13d08ee290dc', 'aaaaaaaa-0000-0000-0000-000000000007', '101', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زُيَيْدِ بْنِ الصَّلْتِ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏إِلَى ‏ ‏الْجُرُفِ ‏ ‏فَنَظَرَ فَإِذَا هُوَ قَدْ احْتَلَمَ وَصَلَّى وَلَمْ يَغْتَسِلْ فَقَالَ ‏ ‏وَاللَّهِ مَا أَرَانِي إِلَّا احْتَلَمْتُ وَمَا شَعَرْتُ وَصَلَّيْتُ وَمَا اغْتَسَلْتُ قَالَ فَاغْتَسَلَ وَغَسَلَ مَا رَأَى فِي ثَوْبِهِ وَنَضَحَ مَا لَمْ يَرَ وَأَذَّنَ ‏ ‏أَوْ أَقَامَ ‏ ‏ثُمَّ صَلَّى بَعْدَ ارْتِفَاعِ الضُّحَى ‏ ‏مُتَمَكِّنًا ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a28bc68a-a386-549f-bc82-bd4409670173', 'aaaaaaaa-0000-0000-0000-000000000007', '102', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ أَبِي حَكِيمٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏غَدَا إِلَى أَرْضِهِ ‏ ‏بِالْجُرُفِ ‏ ‏فَوَجَدَ فِي ثَوْبِهِ احْتِلَامًا فَقَالَ لَقَدْ ‏ ‏ابْتُلِيتُ بِالْاحْتِلَامِ مُنْذُ وُلِّيتُ أَمْرَ النَّاسِ فَاغْتَسَلَ وَغَسَلَ مَا رَأَى فِي ثَوْبِهِ مِنْ الْاحْتِلَامِ ثُمَّ صَلَّى بَعْدَ أَنْ طَلَعَتْ الشَّمْسُ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('37b95caa-77ca-5b1b-96a4-9d3ada1c5445', 'aaaaaaaa-0000-0000-0000-000000000007', '103', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏صَلَّى بِالنَّاسِ الصُّبْحَ ثُمَّ غَدَا إِلَى أَرْضِهِ ‏ ‏بِالْجُرُفِ ‏ ‏فَوَجَدَ فِي ثَوْبِهِ احْتِلَامًا فَقَالَ ‏ ‏إِنَّا لَمَّا أَصَبْنَا ‏ ‏الْوَدَكَ ‏ ‏لَانَتْ الْعُرُوقُ فَاغْتَسَلَ وَغَسَلَ الْاحْتِلَامَ مِنْ ثَوْبِهِ وَعَادَ لِصَلَاتِهِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1ff52728-dec5-56cc-826a-f3c276afb6ff', 'aaaaaaaa-0000-0000-0000-000000000007', '104', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏أَنَّهُ اعْتَمَرَ مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏فِي رَكْبٍ فِيهِمْ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏وَأَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏عَرَّسَ ‏ ‏بِبَعْضِ الطَّرِيقِ قَرِيبًا مِنْ بَعْضِ الْمِيَاهِ فَاحْتَلَمَ ‏ ‏عُمَرُ ‏ ‏وَقَدْ كَادَ أَنْ يُصْبِحَ فَلَمْ يَجِدْ مَعَ الرَّكْبِ مَاءً فَرَكِبَ حَتَّى جَاءَ الْمَاءَ فَجَعَلَ يَغْسِلُ مَا رَأَى مِنْ ذَلِكَ الْاحْتِلَامِ حَتَّى ‏ ‏أَسْفَرَ ‏ ‏فَقَالَ لَهُ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏أَصْبَحْتَ وَمَعَنَا ثِيَابٌ فَدَعْ ثَوْبَكَ يُغْسَلُ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَاعَجَبًا لَكَ يَا ‏ ‏عَمْرُو بْنَ الْعَاصِ ‏ ‏لَئِنْ كُنْتَ تَجِدُ ثِيَابًا أَفَكُلُّ النَّاسِ يَجِدُ ثِيَابًا وَاللَّهِ لَوْ فَعَلْتُهَا لَكَانَتْ سُنَّةً بَلْ أَغْسِلُ مَا رَأَيْتُ ‏ ‏وَأَنْضِحُ مَا لَمْ أَرَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ca532d5-d3de-5986-9e5e-e1f1f5fdf0a5', 'aaaaaaaa-0000-0000-0000-000000000007', '105', '‏ ‏حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْأَةُ ‏ ‏تَرَى فِي الْمَنَامِ مِثْلَ مَا يَرَى الرَّجُلُ أَتَغْتَسِلُ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ فَلْتَغْتَسِلْ فَقَالَتْ لَهَا ‏ ‏عَائِشَةُ ‏ ‏أُفٍّ لَكِ وَهَلْ ‏ ‏تَرَى ذَلِكَ الْمَرْأَةُ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرِبَتْ يَمِينُكِ ‏ ‏وَمِنْ أَيْنَ يَكُونُ الشَّبَهُ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
