insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2fe43c8a-db1a-518b-92cd-945d5972e0f3', 'aaaaaaaa-0000-0000-0000-000000000007', '110', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ حَتَّى إِذَا كُنَّا ‏ ‏بِالْبَيْدَاءِ ‏ ‏أَوْ ‏ ‏بِذَاتِ الْجَيْشِ ‏ ‏انْقَطَعَ عِقْدٌ لِي فَأَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْتِمَاسِهِ وَأَقَامَ النَّاسُ مَعَهُ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ فَأَتَى النَّاسُ إِلَى ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏فَقَالُوا أَلَا ‏ ‏تَرَى مَا صَنَعَتْ ‏ ‏عَائِشَةُ ‏ ‏أَقَامَتْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِالنَّاسِ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعٌ رَأْسَهُ عَلَى فَخِذِي قَدْ نَامَ فَقَالَ حَبَسْتِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسَ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَعَاتَبَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ وَجَعَلَ يَطْعُنُ بِيَدِهِ فِي خَاصِرَتِي فَلَا يَمْنَعُنِي مِنْ التَّحَرُّكِ إِلَّا مَكَانُ رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فَخِذِي فَنَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَصْبَحَ عَلَى غَيْرِ مَاءٍ ‏ ‏فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى آيَةَ التَّيَمُّمِ فَتَيَمَّمُوا فَقَالَ ‏ ‏أُسَيْدُ بْنُ حُضَيْرٍ ‏ ‏مَا هِيَ بِأَوَّلِ بَرَكَتِكُمْ يَا آلَ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَتْ فَبَعَثْنَا الْبَعِيرَ الَّذِي كُنْتُ عَلَيْهِ فَوَجَدْنَا الْعِقْدَ تَحْتَهُ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
