insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('807f67bb-b128-53e3-80ae-a2e4ff193619', 'aaaaaaaa-0000-0000-0000-000000000007', '117', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏مَوْلَاةِ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ النِّسَاءُ يَبْعَثْنَ إِلَى ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏بِالدِّرَجَةِ ‏ ‏فِيهَا ‏ ‏الْكُرْسُفُ ‏ ‏فِيهِ الصُّفْرَةُ مِنْ دَمِ الْحَيْضَةِ يَسْأَلْنَهَا عَنْ الصَّلَاةِ فَتَقُولُ لَهُنَّ ‏ ‏لَا تَعْجَلْنَ حَتَّى تَرَيْنَ ‏ ‏الْقَصَّةَ ‏ ‏الْبَيْضَاءَ ‏ ‏تُرِيدُ بِذَلِكَ الطُّهْرَ مِنْ الْحَيْضَةِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3408d70f-3c6c-5d07-a505-72aa1a2e8f35', 'aaaaaaaa-0000-0000-0000-000000000007', '118', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَنْ ‏ ‏ابْنَةِ زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ بَلَغَهَا ‏ ‏أَنَّ نِسَاءً كُنَّ يَدْعُونَ بِالْمَصَابِيحِ مِنْ جَوْفِ اللَّيْلِ يَنْظُرْنَ إِلَى الطُّهْرِ فَكَانَتْ تَعِيبُ ذَلِكَ عَلَيْهِنَّ وَتَقُولُ مَا كَانَ النِّسَاءُ يَصْنَعْنَ هَذَا ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('21e98bbf-e487-5e77-8e75-a90dc17faebb', 'aaaaaaaa-0000-0000-0000-000000000007', '119', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏أَنَّهُ سَأَلَ ‏ ‏ابْنَ شِهَابٍ ‏ ‏عَنْ الْمَرْأَةِ الْحَامِلِ ‏ ‏تَرَى الدَّمَ قَالَ ‏ ‏تَكُفُّ عَنْ الصَّلَاةِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏قَالَ ‏ ‏مَالِك ‏ ‏وَذَلِكَ الْأَمْرُ عِنْدَنَا ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6050fc8a-3f15-5229-b75b-9cfc28735ff4', 'aaaaaaaa-0000-0000-0000-000000000007', '120', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُرَجِّلُ ‏ ‏رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا حَائِضٌ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c6168b30-d402-5f21-b46f-5a7501ad4388', 'aaaaaaaa-0000-0000-0000-000000000007', '121', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏سَأَلَتْ امْرَأَةٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ أَرَأَيْتَ إِحْدَانَا إِذَا أَصَابَ ثَوْبَهَا الدَّمُ مِنْ الْحَيْضَةِ كَيْفَ تَصْنَعُ فِيهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَصَابَ ثَوْبَ إِحْدَاكُنَّ الدَّمُ مِنْ الْحَيْضَةِ فَلْتَقْرُصْهُ ثُمَّ ‏ ‏لِتَنْضِحْهُ بِالْمَاءِ ثُمَّ لِتُصَلِّ فِيهِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fdbba142-c317-5461-9453-117a1167470b', 'aaaaaaaa-0000-0000-0000-000000000007', '122', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَتْ ‏ ‏فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي لَا أَطْهُرُ أَفَأَدَعُ الصَّلَاةَ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ذَلِكِ عِرْقٌ وَلَيْسَتْ بِالْحَيْضَةِ فَإِذَا أَقْبَلَتْ الْحَيْضَةُ فَاتْرُكِي الصَّلَاةَ فَإِذَا ذَهَبَ قَدْرُهَا فَاغْسِلِي ‏ ‏الدَّمَ عَنْكِ وَصَلِّي ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
